e12 = {title:"Yalta Conference", timestamp:"Feb 1945", description:"Roosevelt, Churchill and Stalin agree on the shape of post-war Europe.", status:"done"}
e13 = {title:"German surrender", timestamp:"8 May 1945", description:"VE Day — Nazi Germany surrenders unconditionally; the war in Europe ends.", status:"done"}
